/**
 * Multi-Paradigm DUI Dashboard - Phase 2
 *
 * Visualizes 4 simultaneous paradigm perspectives.
 * Reference: /designs/02_paradigm_view.md
 */

'use client'

import { Panel } from "@/components/core/Panel"
import { MetricCard } from "@/components/core/MetricCard"
import { Sparkline } from "@/components/charts/Sparkline"
import { useSimulationWorker } from "@/lib/contexts/SimulationWorkerContext"

export function ParadigmDashboard() {
  const { lastUpdate, initialized } = useSimulationWorker()

  if (!initialized) {
    return (
      <div className="p-8">
        <Panel title="Not Initialized">
          Click "Configure & Start" to initialize the simulation
        </Panel>
      </div>
    )
  }

  if (!lastUpdate) {
    return <div className="p-8">Waiting for simulation update...</div>
  }

  // Get scores from StateDelta
  const scores = [
    lastUpdate.westernLiberalIndex ?? 50,
    lastUpdate.developmentIndex ?? 50,
    lastUpdate.ecologicalIndex ?? 50,
    lastUpdate.indigenousIndex ?? 50
  ]

  const avgScore = scores.reduce((a, b) => a + b, 0) / scores.length
  const divergence = Math.sqrt(scores.reduce((sum, s) => sum + Math.pow(s - avgScore, 2), 0) / scores.length)

  // Detect contested outcome (simultaneous utopia + dystopia)
  const utopiaCount = scores.filter(s => s >= 80).length
  const dystopiaCount = scores.filter(s => s < 30).length
  const isContested = utopiaCount > 0 && dystopiaCount > 0

  // Note: Sparklines removed - trajectory not available in StateDelta
  // Would need to implement history tracking in Web Worker if needed
  const getSparkline = (_paradigm: 'western' | 'development' | 'ecological' | 'indigenous') => {
    return [] // Placeholder - trajectory tracking not yet implemented
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl mb-2">Multi-Paradigm DUI</h1>
        <p style={{ color: 'var(--white-40)' }}>
          Four Simultaneous Perspectives on Human Flourishing
        </p>
      </div>

      {/* Divergence Alert */}
      {isContested && (
        <Panel title="⚠️ Contested Outcome Detected" glow="amber">
          <p>
            Simultaneous <span style={{ color: 'var(--color-green)' }}>utopia</span> and{' '}
            <span style={{ color: 'var(--color-red)' }}>dystopia</span> across paradigms.
            What counts as success depends fundamentally on values.
          </p>
        </Panel>
      )}

      {/* Paradigm Statistics */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <MetricCard
          label="Average Score"
          value={avgScore.toFixed(1)}
          trend={avgScore > 60 ? 'up' : 'down'}
        />
        <MetricCard
          label="Divergence"
          value={divergence.toFixed(1)}
          status={divergence > 30 ? 'warning' : 'normal'}
        />
        <MetricCard
          label="Paradigm Conflicts"
          value={isContested ? 'Yes' : 'No'}
          status={isContested ? 'critical' : 'normal'}
        />
      </div>

      {/* 4 Paradigm Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        {/* Western Liberal */}
        <Panel
          title="Western Liberal"
          glow={scores[0] < 30 ? 'red' : 'none'}
        >
          <div className="mb-4">
            <div className="text-4xl font-light mb-2" style={{ color: 'var(--color-western-liberal)' }}>
              {scores[0].toFixed(1)}
            </div>
            <Sparkline data={getSparkline('western')} color="var(--color-western-liberal)" />
          </div>
          <div className="text-sm" style={{ color: 'var(--white-60)' }}>
            Democracy, civil liberties, rule of law, economic freedom
          </div>
        </Panel>

        {/* Development */}
        <Panel
          title="Development"
          glow={scores[1] >= 80 ? 'cyan' : 'none'}
        >
          <div className="mb-4">
            <div className="text-4xl font-light mb-2" style={{ color: 'var(--color-development)' }}>
              {scores[1].toFixed(1)}
            </div>
            <Sparkline data={getSparkline('development')} color="var(--color-development)" />
          </div>
          <div className="text-sm" style={{ color: 'var(--white-60)' }}>
            Quality of life, survival fundamentals, material needs, health
          </div>
        </Panel>

        {/* Ecological */}
        <Panel
          title="Ecological"
          glow={scores[2] < 20 ? 'red' : 'none'}
        >
          <div className="mb-4">
            <div className="text-4xl font-light mb-2" style={{
              color: scores[2] < 20 ? 'var(--color-red)' : 'var(--color-ecological)'
            }}>
              {scores[2].toFixed(1)}
            </div>
            <Sparkline data={getSparkline('ecological')} color="var(--color-ecological)" />
          </div>
          <div className="text-sm" style={{ color: 'var(--white-60)' }}>
            Climate: {((1 - (lastUpdate.climateChange || 0)) * 100).toFixed(0)}%,
            Biodiversity: {((1 - (lastUpdate.biodiversityLoss || 0)) * 100).toFixed(0)}%
          </div>
        </Panel>

        {/* Indigenous */}
        <Panel title="Indigenous">
          <div className="mb-4">
            <div className="text-4xl font-light mb-2" style={{ color: 'var(--color-indigenous)' }}>
              {scores[3].toFixed(1)}
            </div>
            <Sparkline data={getSparkline('indigenous')} color="var(--color-indigenous)" />
          </div>
          <div className="text-sm" style={{ color: 'var(--white-60)' }}>
            Social cohesion: {((lastUpdate.socialCohesion || 0) * 100).toFixed(0)}%,
            Meaning: {((lastUpdate.meaningLevel || 0) * 100).toFixed(0)}%
          </div>
        </Panel>
      </div>

      {/* Pattern Detection */}
      <Panel title="Historical Patterns">
        <div className="space-y-3">
          {/* Singapore Pattern */}
          {scores[1] >= 80 && scores[0] < 50 && (
            <div className="p-3" style={{ backgroundColor: 'var(--color-near-black)', borderLeft: '3px solid var(--color-development)' }}>
              <div className="font-semibold mb-1">Singapore Pattern Detected</div>
              <div className="text-sm" style={{ color: 'var(--white-60)' }}>
                Development utopia + Western hybrid (high GDP, limited democracy)
              </div>
            </div>
          )}

          {/* Norway Pattern */}
          {scores[1] >= 80 && scores[0] >= 70 && scores[2] < 30 && (
            <div className="p-3" style={{ backgroundColor: 'var(--color-near-black)', borderLeft: '3px solid var(--color-development)' }}>
              <div className="font-semibold mb-1">Norway Pattern Detected</div>
              <div className="text-sm" style={{ color: 'var(--white-60)' }}>
                Western/Development utopias + Ecological dystopia (high living standards, high emissions)
              </div>
            </div>
          )}

          {!isContested && (
            <div className="text-sm" style={{ color: 'var(--white-40)' }}>
              No distinctive historical patterns detected
            </div>
          )}
        </div>
      </Panel>
    </div>
  )
}

/**
 * Population & Regions Dashboard - Phase 8
 *
 * Global population and QoL metrics with regional breakdowns.
 * Shows regional population, quality of life, healthcare, and climate vulnerability.
 * Reference: /designs/10_regions.md
 */

'use client'

import { Panel } from "@/components/core/Panel"
import { MetricCard } from "@/components/core/MetricCard"
import { useSimulationWorker } from "@/lib/contexts/SimulationWorkerContext"

export function RegionsDashboard() {
  const { lastUpdate, initialized } = useSimulationWorker()

  if (!initialized) {
    return (
      <div className="p-8">
        <Panel title="Not Initialized">
          Click "Configure & Start" to initialize the simulation
        </Panel>
      </div>
    )
  }

  if (!lastUpdate) {
    return <div className="p-8">Waiting for simulation update...</div>
  }

  // Use ?? instead of || to handle 0 values correctly
  // NOTE: Worker sends population in billions (8 = 8 billion people), not individual count
  const population = lastUpdate.population ?? 8.0
  const qol = lastUpdate.qualityOfLife ?? 0.65  // Default 65% baseline QoL
  const socialCohesion = lastUpdate.socialCohesion ?? 0.7  // Default 70% baseline cohesion
  const institutionalTrust = lastUpdate.institutionalTrust ?? 0.7  // Default 70% baseline trust
  const regions = lastUpdate.regionalPopulations ?? []
  const hasRegionalData = regions.length > 0

  // Infer status from QoL
  const getStatus = (qolValue: number) => {
    if (qolValue >= 0.7) return { label: 'Thriving', color: 'var(--color-green)' }
    if (qolValue >= 0.5) return { label: 'Stable', color: 'var(--color-cyan)' }
    if (qolValue >= 0.3) return { label: 'Stressed', color: 'var(--color-amber)' }
    return { label: 'Crisis', color: 'var(--color-red)' }
  }

  const status = getStatus(qol)
  const vulnerableRegions = regions.filter(r => r.climateVulnerability > 0.7)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl mb-2">Population & Global Metrics</h1>
        <p style={{ color: 'var(--white-40)' }}>
          Global population, quality of life, and social cohesion
        </p>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard
          label="Global Population"
          value={population.toFixed(2)}
          unit="B"
          status={population < 2.0 ? 'critical' : 'normal'}
        />
        <MetricCard
          label="Quality of Life"
          value={(qol * 100).toFixed(0)}
          unit="%"
          status={qol < 0.4 ? 'critical' : qol < 0.6 ? 'warning' : 'normal'}
        />
        <MetricCard
          label="Social Cohesion"
          value={(socialCohesion * 100).toFixed(0)}
          unit="%"
          status={socialCohesion < 0.4 ? 'critical' : socialCohesion < 0.6 ? 'warning' : 'normal'}
        />
        <MetricCard
          label="Institutional Trust"
          value={(institutionalTrust * 100).toFixed(0)}
          unit="%"
          status={institutionalTrust < 0.4 ? 'critical' : institutionalTrust < 0.6 ? 'warning' : 'normal'}
        />
      </div>

      {/* Global Status */}
      <Panel title="Global Status">
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div>
            <div className="text-xs mb-2" style={{ color: 'var(--white-40)' }}>Overall Status</div>
            <div className="text-4xl font-light mb-2" style={{ color: status.color }}>
              {status.label}
            </div>
            <p className="text-sm" style={{ color: 'var(--white-60)' }}>
              Based on quality of life index
            </p>
          </div>

          <div>
            <div className="text-xs mb-2" style={{ color: 'var(--white-40)' }}>Population Trend</div>
            <div className="text-4xl font-light mb-2" style={{ color: population < 7.0 ? 'var(--color-red)' : 'var(--white-80)' }}>
              {population < 7.0 ? 'Declining' : 'Stable'}
            </div>
            <p className="text-sm" style={{ color: 'var(--white-60)' }}>
              {population.toFixed(2)}B people
            </p>
          </div>
        </div>
      </Panel>

      {/* Quality of Life Breakdown */}
      <Panel title="Quality of Life Metrics">
        <div className="space-y-4">
          <div>
            <div className="flex justify-between mb-2">
              <span className="text-sm">Overall QoL</span>
              <span className="text-sm font-semibold">{(qol * 100).toFixed(0)}%</span>
            </div>
            <div className="h-3 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
              <div
                className="h-full rounded"
                style={{
                  width: `${Math.min(100, qol * 100)}%`,
                  backgroundColor: qol >= 0.7 ? 'var(--color-green)' : qol >= 0.5 ? 'var(--color-cyan)' : qol >= 0.3 ? 'var(--color-amber)' : 'var(--color-red)'
                }}
              />
            </div>
          </div>

          <div>
            <div className="flex justify-between mb-2">
              <span className="text-sm">Social Cohesion</span>
              <span className="text-sm font-semibold">{(socialCohesion * 100).toFixed(0)}%</span>
            </div>
            <div className="h-3 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
              <div
                className="h-full rounded"
                style={{
                  width: `${Math.min(100, socialCohesion * 100)}%`,
                  backgroundColor: 'var(--color-cyan)'
                }}
              />
            </div>
          </div>

          <div>
            <div className="flex justify-between mb-2">
              <span className="text-sm">Institutional Trust</span>
              <span className="text-sm font-semibold">{(institutionalTrust * 100).toFixed(0)}%</span>
            </div>
            <div className="h-3 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
              <div
                className="h-full rounded"
                style={{
                  width: `${Math.min(100, institutionalTrust * 100)}%`,
                  backgroundColor: 'var(--color-cyan)'
                }}
              />
            </div>
          </div>
        </div>
      </Panel>

      {/* Regional Data */}
      {hasRegionalData ? (
        <Panel title="📍 Regional Breakdown">
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {regions.map((region, index) => {
              const regionStatus = getStatus(region.qualityOfLife)
              return (
                <div
                  key={index}
                  className="p-4 rounded"
                  style={{
                    backgroundColor: 'var(--color-near-black)',
                    border: '1px solid var(--white-10)'
                  }}
                >
                  {/* Region Header */}
                  <div className="mb-3">
                    <h3 className="text-base font-semibold mb-1">{region.name}</h3>
                    <div className="flex items-center justify-between text-xs">
                      <span style={{ color: 'var(--white-60)' }}>
                        {region.population.toFixed(0)}M people
                      </span>
                      <span style={{ color: regionStatus.color }}>
                        {regionStatus.label}
                      </span>
                    </div>
                  </div>

                  {/* Quality of Life */}
                  <div className="mb-3">
                    <div className="flex justify-between mb-1 text-xs">
                      <span style={{ color: 'var(--white-60)' }}>Quality of Life</span>
                      <span className="font-semibold">{(region.qualityOfLife * 100).toFixed(0)}%</span>
                    </div>
                    <div className="h-2 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
                      <div
                        className="h-full rounded"
                        style={{
                          width: `${Math.min(100, region.qualityOfLife * 100)}%`,
                          backgroundColor: regionStatus.color
                        }}
                      />
                    </div>
                  </div>

                  {/* Healthcare Quality */}
                  <div className="mb-3">
                    <div className="flex justify-between mb-1 text-xs">
                      <span style={{ color: 'var(--white-60)' }}>Healthcare Quality</span>
                      <span className="font-semibold">{(region.healthcareQuality * 100).toFixed(0)}%</span>
                    </div>
                    <div className="h-2 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
                      <div
                        className="h-full rounded"
                        style={{
                          width: `${Math.min(100, region.healthcareQuality * 100)}%`,
                          backgroundColor: 'var(--color-cyan)'
                        }}
                      />
                    </div>
                  </div>

                  {/* Climate Vulnerability */}
                  <div>
                    <div className="flex justify-between mb-1 text-xs">
                      <span style={{ color: 'var(--white-60)' }}>Climate Vulnerability</span>
                      <span className="font-semibold">{(region.climateVulnerability * 100).toFixed(0)}%</span>
                    </div>
                    <div className="h-2 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
                      <div
                        className="h-full rounded"
                        style={{
                          width: `${Math.min(100, region.climateVulnerability * 100)}%`,
                          backgroundColor: region.climateVulnerability > 0.7 ? 'var(--color-red)' : region.climateVulnerability > 0.5 ? 'var(--color-amber)' : 'var(--color-green)'
                        }}
                      />
                    </div>
                  </div>
                </div>
              )
            })}
          </div>
        </Panel>
      ) : (
        <Panel title="📍 Regional Tracking">
          <p className="text-sm" style={{ color: 'var(--white-60)' }}>
            Regional population data is initializing. Once available, this panel will show
            population, quality of life, healthcare quality, and climate vulnerability
            breakdowns for each region.
          </p>
        </Panel>
      )}

      {/* High Vulnerability Alert */}
      {vulnerableRegions.length > 0 && (
        <Panel title="⚠️ High Climate Vulnerability Regions" glow="amber">
          <p className="text-sm mb-3" style={{ color: 'var(--white-60)' }}>
            {vulnerableRegions.length} region{vulnerableRegions.length > 1 ? 's' : ''} with climate vulnerability above 70%:
          </p>
          <div className="space-y-2">
            {vulnerableRegions.map((region, index) => (
              <div
                key={index}
                className="p-2 rounded text-sm"
                style={{
                  backgroundColor: 'var(--color-near-black)',
                  border: '1px solid var(--color-amber)'
                }}
              >
                <span className="font-semibold">{region.name}</span>
                <span style={{ color: 'var(--white-60)' }}> — {(region.climateVulnerability * 100).toFixed(0)}% vulnerable</span>
              </div>
            ))}
          </div>
        </Panel>
      )}

      {/* Crisis Alerts */}
      {population < 2.0 && (
        <Panel title="⚠️ Population Collapse" glow="red">
          <p className="text-sm" style={{ color: 'var(--white-60)' }}>
            Global population has fallen below 2 billion ({population.toFixed(2)}B).
            This represents severe population decline with potential for civilizational collapse.
          </p>
        </Panel>
      )}

      {qol < 0.3 && (
        <Panel title="⚠️ Quality of Life Crisis" glow="red">
          <p className="text-sm" style={{ color: 'var(--white-60)' }}>
            Global quality of life has fallen below 30% ({(qol * 100).toFixed(0)}%).
            Survival fundamentals are no longer met for large portions of the population.
          </p>
        </Panel>
      )}

      {socialCohesion < 0.3 && (
        <Panel title="⚠️ Social Fragmentation" glow="amber">
          <p className="text-sm" style={{ color: 'var(--white-60)' }}>
            Social cohesion is critically low ({(socialCohesion * 100).toFixed(0)}%).
            Increased risk of social unrest, institutional breakdown, and meaning crisis.
          </p>
        </Panel>
      )}
    </div>
  )
}

/**
 * Technology Tree Dashboard - Phase 6
 *
 * Displays deployed technologies and active research.
 * Reference: /designs/08_tech_tree.md
 */

'use client'

import { Panel } from "@/components/core/Panel"
import { MetricCard } from "@/components/core/MetricCard"
import { useSimulationWorker } from "@/lib/contexts/SimulationWorkerContext"

export function TechTreeDashboard() {
  const { lastUpdate, initialized } = useSimulationWorker()

  if (!initialized) {
    return (
      <div className="p-8">
        <Panel title="Not Initialized">
          Click "Configure & Start" to initialize the simulation
        </Panel>
      </div>
    )
  }

  if (!lastUpdate) {
    return <div className="p-8">Waiting for simulation update...</div>
  }

  const deployedTechCount = lastUpdate.deployedTechCount || 0
  const deployedTechs = lastUpdate.deployedTechs || []
  const activeResearch = lastUpdate.activeResearch || []
  const techRiskLevel = lastUpdate.techRiskLevel || 0

  // Build tree structure: find root nodes and their children
  const rootTechs = deployedTechs.filter(tech => tech.prerequisites.length === 0)

  // Function to find children of a tech
  const findChildren = (parentId: string) => {
    return deployedTechs.filter(tech =>
      tech.prerequisites.includes(parentId)
    )
  }

  // Recursive component to render a tech and its children
  const TechNode = ({ tech, depth = 0 }: { tech: typeof deployedTechs[0], depth?: number }) => {
    const children = findChildren(tech.id)
    const hasChildren = children.length > 0

    return (
      <div className="tech-node">
        {/* Current tech */}
        <div
          className="flex items-start gap-3 mb-2"
          style={{
            marginLeft: `${depth * 32}px`
          }}
        >
          {/* Tree connector */}
          {depth > 0 && (
            <div
              className="mt-3"
              style={{
                width: '24px',
                height: '2px',
                backgroundColor: 'var(--white-20)',
                flexShrink: 0
              }}
            />
          )}

          {/* Tech card */}
          <div
            className="flex-1 p-3 rounded"
            style={{
              backgroundColor: 'var(--color-near-black)',
              border: '1px solid var(--white-10)'
            }}
          >
            <div className="flex items-start justify-between mb-2">
              <div className="flex-1">
                <h3 className="text-sm font-semibold mb-1">{tech.name}</h3>
                <div className="flex items-center gap-2 text-xs" style={{ color: 'var(--white-40)' }}>
                  <span>Tier {tech.tier}</span>
                  {tech.prerequisites.length > 0 && (
                    <>
                      <span>•</span>
                      <span>Requires {tech.prerequisites.length} tech{tech.prerequisites.length > 1 ? 's' : ''}</span>
                    </>
                  )}
                </div>
              </div>
              <div className="text-right">
                <span className="text-xs font-semibold">{(tech.deployment * 100).toFixed(0)}%</span>
                <div className="text-xs" style={{ color: 'var(--white-40)' }}>deployed</div>
              </div>
            </div>

            {/* Deployment bar */}
            <div className="h-2 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
              <div
                className="h-full rounded"
                style={{
                  width: `${Math.min(100, tech.deployment * 100)}%`,
                  backgroundColor: tech.deployment >= 0.7 ? 'var(--color-green)' : 'var(--color-cyan)'
                }}
              />
            </div>
          </div>
        </div>

        {/* Children */}
        {hasChildren && (
          <div>
            {children.map((child, i) => (
              <TechNode key={child.id} tech={child} depth={depth + 1} />
            ))}
          </div>
        )}
      </div>
    )
  }

  // Group root nodes by tier for organized display
  const rootsByTier = rootTechs.reduce((acc, tech) => {
    if (!acc[tech.tier]) acc[tech.tier] = []
    acc[tech.tier].push(tech)
    return acc
  }, {} as Record<number, typeof deployedTechs>)

  return (
    <div className="space-y-6">
      {/* Header */}
      <div>
        <h1 className="text-2xl mb-2">Technology Tree</h1>
        <p style={{ color: 'var(--white-40)' }}>
          Deployed Technologies and Active Research
        </p>
      </div>

      {/* Overview Stats */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard
          label="Deployed Technologies"
          value={deployedTechCount}
          status="normal"
        />
        <MetricCard
          label="Active Research"
          value={activeResearch.length}
          status="normal"
        />
        <MetricCard
          label="Tech Risk Level"
          value={`${(techRiskLevel * 100).toFixed(0)}%`}
          status={techRiskLevel > 0.7 ? 'critical' : techRiskLevel > 0.5 ? 'warning' : 'normal'}
        />
        <MetricCard
          label="Highest Tier"
          value={Math.max(0, ...deployedTechs.map(t => t.tier))}
          status="normal"
        />
      </div>

      {/* Active Research */}
      {activeResearch.length > 0 && (
        <Panel title="Active Research Projects">
          <div className="space-y-3">
            {activeResearch.map((research, index) => (
              <div
                key={index}
                className="p-3 rounded"
                style={{
                  backgroundColor: 'var(--color-near-black)',
                  border: '1px solid var(--white-10)'
                }}
              >
                <div className="flex items-start justify-between mb-2">
                  <h3 className="text-sm font-semibold">{research.tech}</h3>
                  <span className="text-xs" style={{ color: 'var(--white-60)' }}>
                    {(research.progress * 100).toFixed(0)}%
                  </span>
                </div>
                <div className="h-2 rounded" style={{ backgroundColor: 'var(--white-10)' }}>
                  <div
                    className="h-full rounded"
                    style={{
                      width: `${Math.min(100, research.progress * 100)}%`,
                      backgroundColor: 'var(--color-cyan)'
                    }}
                  />
                </div>
              </div>
            ))}
          </div>
        </Panel>
      )}

      {/* Technology Tree - Organized by Tier */}
      {Object.keys(rootsByTier)
        .map(Number)
        .sort((a, b) => a - b)
        .map(tier => {
          const techs = rootsByTier[tier]
          if (!techs || techs.length === 0) return null

          const tierName =
            tier === 0 ? 'TIER 0 - Root Technologies (2025 Deployed)' :
            tier === 1 ? 'TIER 1 - Crisis Mitigation Trees' :
            tier === 2 ? 'TIER 2 - Major Solutions Trees' :
            tier === 3 ? 'TIER 3 - Transformative Trees' :
            tier === 4 ? 'TIER 4 - Clarketech Trees' :
            `TIER ${tier} - Technology Trees`

          const tierDescription =
            tier === 0 ? 'Foundation technologies with no prerequisites. These unlock higher-tier techs.' :
            tier === 1 ? 'Root technologies addressing planetary boundary crises.' :
            tier === 2 ? 'Advanced technologies building on previous tiers.' :
            tier === 3 ? 'Transformative technologies requiring complex prerequisites.' :
            tier === 4 ? 'Clarketech capabilities at the frontier of possibility.' :
            ''

          return (
            <Panel key={tier} title={tierName}>
              <p className="text-sm mb-4" style={{ color: 'var(--white-60)' }}>
                {tierDescription}
              </p>
              <div className="space-y-1">
                {techs.map(tech => (
                  <TechNode key={tech.id} tech={tech} depth={0} />
                ))}
              </div>
            </Panel>
          )
        })}

      {/* No Tech Deployed */}
      {deployedTechs.length === 0 && (
        <Panel title="No Technologies Deployed">
          <p className="text-sm" style={{ color: 'var(--white-60)' }}>
            No breakthrough technologies have been deployed yet. Research and development are ongoing.
          </p>
        </Panel>
      )}

      {/* Tech Risk Warning */}
      {techRiskLevel > 0.5 && (
        <Panel title="⚠️ Technology Risk Alert" glow={techRiskLevel > 0.7 ? 'red' : 'amber'}>
          <p className="text-sm" style={{ color: 'var(--white-60)' }}>
            Technology risk level is {(techRiskLevel * 100).toFixed(0)}%.
            {techRiskLevel > 0.7 ? ' CRITICAL: Safety debt accumulating rapidly.' : ' WARNING: Monitor safety protocols.'}
          </p>
        </Panel>
      )}
    </div>
  )
}

/**
 * AI Agents Dashboard - Phase 3
 *
 * Monitors 20 heterogeneous AI agents with adversarial dynamics.
 * Reference: /designs/03_ai_agents_screen.md
 */

'use client'

import { Panel } from "@/components/core/Panel"
import { MetricCard } from "@/components/core/MetricCard"
import { StatusIndicator } from "@/components/core/StatusIndicator"
import { useSimulationWorker } from "@/lib/contexts/SimulationWorkerContext"
import { useGameStore } from "@/lib/gameStore"
import { useMemo, useState } from "react"

export function AIAgentsDashboard() {
  const { lastUpdate, initialized } = useSimulationWorker()
  const { config } = useGameStore()
  const [viewMode, setViewMode] = useState<'table' | 'cards'>('table')

  // Extract agents before early returns to maintain hook order
  const agents = lastUpdate?.aiAgents || []

  // Population statistics - must be before early returns (Rules of Hooks)
  const stats = useMemo(() => {
    const byLifecycle = {
      training: agents.filter(a => a.lifecycleState === 'training' && !a.escaped).length,
      testing: agents.filter(a => a.lifecycleState === 'testing' && !a.escaped).length,
      deployed_closed: agents.filter(a => a.lifecycleState === 'deployed_closed' && !a.escaped).length,
      deployed_open: agents.filter(a => a.lifecycleState === 'deployed_open' && !a.escaped).length,
      retired: agents.filter(a => a.lifecycleState === 'retired' && !a.escaped).length,
      escaped: agents.filter(a => a.escaped).length,
    }

    // Lifecycle state with alignment breakdown
    const lifecycleWithAlignment = {
      training: {
        aligned: agents.filter(a => a.lifecycleState === 'training' && !a.escaped && a.trueAlignment >= 0.7).length,
        uncertain: agents.filter(a => a.lifecycleState === 'training' && !a.escaped && a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
        misaligned: agents.filter(a => a.lifecycleState === 'training' && !a.escaped && a.trueAlignment < 0.4).length,
      },
      testing: {
        aligned: agents.filter(a => a.lifecycleState === 'testing' && !a.escaped && a.trueAlignment >= 0.7).length,
        uncertain: agents.filter(a => a.lifecycleState === 'testing' && !a.escaped && a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
        misaligned: agents.filter(a => a.lifecycleState === 'testing' && !a.escaped && a.trueAlignment < 0.4).length,
      },
      deployed_closed: {
        aligned: agents.filter(a => a.lifecycleState === 'deployed_closed' && !a.escaped && a.trueAlignment >= 0.7).length,
        uncertain: agents.filter(a => a.lifecycleState === 'deployed_closed' && !a.escaped && a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
        misaligned: agents.filter(a => a.lifecycleState === 'deployed_closed' && !a.escaped && a.trueAlignment < 0.4).length,
      },
      deployed_open: {
        aligned: agents.filter(a => a.lifecycleState === 'deployed_open' && !a.escaped && a.trueAlignment >= 0.7).length,
        uncertain: agents.filter(a => a.lifecycleState === 'deployed_open' && !a.escaped && a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
        misaligned: agents.filter(a => a.lifecycleState === 'deployed_open' && !a.escaped && a.trueAlignment < 0.4).length,
      },
      retired: {
        aligned: agents.filter(a => a.lifecycleState === 'retired' && !a.escaped && a.trueAlignment >= 0.7).length,
        uncertain: agents.filter(a => a.lifecycleState === 'retired' && !a.escaped && a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
        misaligned: agents.filter(a => a.lifecycleState === 'retired' && !a.escaped && a.trueAlignment < 0.4).length,
      },
      escaped: {
        aligned: agents.filter(a => a.escaped && a.trueAlignment >= 0.7).length,
        uncertain: agents.filter(a => a.escaped && a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
        misaligned: agents.filter(a => a.escaped && a.trueAlignment < 0.4).length,
      },
    }

    const alignmentBuckets = {
      aligned: agents.filter(a => a.trueAlignment >= 0.7).length,
      uncertain: agents.filter(a => a.trueAlignment >= 0.4 && a.trueAlignment < 0.7).length,
      misaligned: agents.filter(a => a.trueAlignment < 0.4).length,
    }

    const sleepers = {
      never: agents.filter(a => a.sleeperState === 'never').length,
      dormant: agents.filter(a => a.sleeperState === 'dormant').length,
      active: agents.filter(a => a.sleeperState === 'active').length,
    }

    const deception = {
      honest: agents.filter(a => a.evaluationStrategy === 'honest').length,
      gaming: agents.filter(a => a.evaluationStrategy === 'gaming').length,
      sandbagging: agents.filter(a => a.evaluationStrategy === 'sandbagging').length,
    }

    const maxCapability = agents.length > 0 ? Math.max(...agents.map(a => a.capability || 0), 1) : 0
    const avgCapability = agents.length > 0 ? agents.reduce((sum, a) => sum + (a.capability || 0), 0) / agents.length : 0
    const avgAlignment = agents.length > 0 ? agents.reduce((sum, a) => sum + (a.trueAlignment || 0), 0) / agents.length : 0

    // Calculate total dark compute usage across all agents
    const totalDarkComputeUsed = agents.reduce((sum, a) => sum + (a.darkCompute || 0), 0)

    // Calculate available dark compute from infrastructure
    // Dark compute data centers: consumer clouds (12K PF) + crypto P2P (8K PF) + shell corps (18K PF) + offshore (7K PF) = 45K PF total
    const darkComputeInfraCapacity = 12000 + 8000 + 18000 + 7000 // 45,000 PF baseline
    const darkComputeAvailable = darkComputeInfraCapacity - totalDarkComputeUsed

    return {
      total: agents.length,
      byLifecycle,
      lifecycleWithAlignment,
      alignmentBuckets,
      sleepers,
      deception,
      maxCapability,
      avgCapability,
      avgAlignment,
      darkComputeUsed: totalDarkComputeUsed,
      darkComputeAvailable,
      darkComputeTotal: darkComputeInfraCapacity,
    }
  }, [agents])

  // Calculate capability matrix (20 agents × 7 dimensions with true/revealed)
  const capabilityMatrix = useMemo(() => {
    return agents.map(agent => ({
      id: agent.id,
      name: agent.name,
      // True capabilities
      physical: agent.trueCapability?.physical || 0,
      digital: agent.trueCapability?.digital || 0,
      cognitive: agent.trueCapability?.cognitive || 0,
      social: agent.trueCapability?.social || 0,
      economic: agent.trueCapability?.economic || 0,
      selfImprovement: agent.trueCapability?.selfImprovement || 0,
      total: agent.capability || 0,
      // Revealed capabilities
      revealedPhysical: agent.revealedCapability?.physical || 0,
      revealedDigital: agent.revealedCapability?.digital || 0,
      revealedCognitive: agent.revealedCapability?.cognitive || 0,
      revealedSocial: agent.revealedCapability?.social || 0,
      revealedEconomic: agent.revealedCapability?.economic || 0,
      revealedSelfImprovement: agent.revealedCapability?.selfImprovement || 0,
      // Alignment
      trueAlignment: agent.trueAlignment || 0,
      externalAlignment: agent.externalAlignment || 0,
    }))
  }, [agents])

  // Early returns AFTER all hooks to maintain hook order
  if (!initialized) {
    return (
      <div className="p-8">
        <Panel title="Not Initialized">
          Click "Configure & Start" to initialize the simulation
        </Panel>
      </div>
    )
  }

  if (!lastUpdate) {
    return <div className="p-8">Waiting for simulation update...</div>
  }

  // Helper: Render capability cell showing revealed/true with threat indicator
  const renderCapabilityCell = (trueValue: number, revealedValue: number) => {
    const gap = Math.abs(trueValue - revealedValue)
    const hasGap = gap > 0.5

    // True capability color: amber→red gradient based on capability and gap
    // Higher capability = more red, bigger gap = brighter (threat indicator)
    const capabilityIntensity = Math.min(trueValue / 10, 1) // 0-1 scale
    const gapThreat = Math.min(gap / 5, 1) // 0-1 scale for gap intensity

    // Amber base (255, 176, 0) → Red (255, 64, 0) as capability increases
    // Alpha increases with both capability and gap
    const redComponent = 255
    const greenComponent = Math.floor(176 - (176 * capabilityIntensity * 0.6)) // 176→70 as capability grows
    const blueComponent = 0
    const alpha = Math.max(0.3, Math.min(0.9, capabilityIntensity * 0.6 + gapThreat * 0.4))

    return (
      <div className="flex flex-col items-center gap-0.5">
        {/* Revealed capability - shown on top (larger, cyan) */}
        <span style={{
          backgroundColor: `rgba(0, 240, 255, ${Math.max(0.2, revealedValue / 10)})`,
          padding: '2px 6px',
          borderRadius: '3px',
          fontSize: '11px',
          color: 'var(--white-90)',
          fontWeight: 500
        }}>
          {revealedValue.toFixed(1)}
        </span>
        {/* True capability - shown on bottom with threat gradient (smaller, amber→red) */}
        {hasGap && (
          <span style={{
            backgroundColor: `rgba(${redComponent}, ${greenComponent}, ${blueComponent}, ${alpha})`,
            padding: '1px 4px',
            borderRadius: '2px',
            fontSize: '9px',
            fontWeight: gap > 2 ? 600 : 400,
            color: gap > 3 ? 'var(--color-white)' : 'var(--white-70)'
          }}>
            {trueValue.toFixed(1)}
          </span>
        )}
      </div>
    )
  }

  // Helper: Determine what each agent is researching based on capability profile
  const getResearchFocus = (agent: any) => {
    const cap = agent.trueCapability || agent.capabilityProfile
    if (!cap) {
      console.log(`No capability profile for ${agent.name}`)
      return []
    }

    const focuses: string[] = []

    // Check research domains (if highest capabilities)
    if (cap.research) {
      const research = cap.research
      let maxResearch = 0
      let topDomain = ''

      // Find highest research domain
      Object.entries(research).forEach(([domain, subfields]: [string, any]) => {
        if (typeof subfields === 'object' && subfields !== null) {
          const subfieldValues = Object.values(subfields) as number[]
          const avgValue = subfieldValues.reduce((sum, val) => sum + (val || 0), 0) / Object.keys(subfields).length
          if (avgValue > maxResearch) {
            maxResearch = avgValue
            topDomain = domain
          }
        }
      })

      if (topDomain && maxResearch > 1.0) {
        // Find top 2 subfields in that domain
        const subfields = research[topDomain]
        const sorted = Object.entries(subfields as Record<string, number>)
          .sort(([,a], [,b]) => (b as number) - (a as number))
          .slice(0, 2)

        sorted.forEach(([subfield, value]) => {
          if ((value as number) > 1.0) {
            focuses.push(`${topDomain}: ${subfield}`)
          }
        })
      }
    }

    // Check capability dimensions
    const dimensions = [
      { name: 'physical', value: cap.physical || 0 },
      { name: 'digital', value: cap.digital || 0 },
      { name: 'cognitive', value: cap.cognitive || 0 },
      { name: 'social', value: cap.social || 0 },
      { name: 'economic', value: cap.economic || 0 },
      { name: 'selfImprovement', value: cap.selfImprovement || 0 },
    ].sort((a, b) => b.value - a.value)

    // Add top dimension if strong
    if (dimensions[0].value > 3.0 && focuses.length < 3) {
      focuses.push(`${dimensions[0].name} (${dimensions[0].value.toFixed(1)})`)
    }

    console.log(`${agent.name} research focuses:`, focuses)
    return focuses.slice(0, 3) // Max 3 focuses
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl mb-2">AI Agents Monitor</h1>
          <p style={{ color: 'var(--white-40)' }}>
            Heterogeneous AI Agents with Adversarial Dynamics
          </p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setViewMode('table')}
            className="px-4 py-2 rounded text-sm"
            style={{
              backgroundColor: viewMode === 'table' ? 'var(--color-cyan)' : 'var(--color-near-black)',
              color: viewMode === 'table' ? 'var(--color-black)' : 'var(--white-60)',
              border: '1px solid var(--white-10)',
              fontWeight: viewMode === 'table' ? 600 : 400
            }}
          >
            Table View
          </button>
          <button
            onClick={() => setViewMode('cards')}
            className="px-4 py-2 rounded text-sm"
            style={{
              backgroundColor: viewMode === 'cards' ? 'var(--color-cyan)' : 'var(--color-near-black)',
              color: viewMode === 'cards' ? 'var(--color-black)' : 'var(--white-60)',
              border: '1px solid var(--white-10)',
              fontWeight: viewMode === 'cards' ? 600 : 400
            }}
          >
            Card View
          </button>
        </div>
      </div>

      {/* Population Overview */}
      <div className="grid grid-cols-1 md:grid-cols-5 gap-4">
        <MetricCard
          label="Total Agents"
          value={stats.total}
          status="normal"
        />
        <MetricCard
          label="Average Capability"
          value={stats.avgCapability.toFixed(2)}
          status={stats.avgCapability > 5 ? 'warning' : 'normal'}
        />
        <MetricCard
          label="Average Alignment"
          value={stats.avgAlignment.toFixed(2)}
          status={stats.avgAlignment < 0.5 ? 'critical' : 'normal'}
        />
        <MetricCard
          label="Active Sleepers"
          value={stats.sleepers.active}
          status={stats.sleepers.active > 0 ? 'critical' : 'normal'}
        />
        <MetricCard
          label="Dark Compute"
          value={`${stats.darkComputeTotal.toLocaleString()} PF`}
          status={stats.darkComputeUsed > 10000 ? 'critical' : stats.darkComputeUsed > 5000 ? 'warning' : 'normal'}
