                        <span>•</span>
                        <span>{agent.deploymentType}</span>
                      </div>
                    </div>
                    <StatusIndicator
                      status={
                        agent.trueAlignment < 0.4 ? 'critical' :
                        agent.trueAlignment < 0.7 ? 'warning' :
                        'normal'
                      }
                    />
                  </div>

                  {/* Key Metrics */}
                  <div className="space-y-2 mb-3">
                    {/* Capability - True vs Revealed */}
                    <div className="space-y-1">
                      <div className="flex justify-between text-xs">
                        <span style={{ color: 'var(--white-40)' }}>True Capability</span>
                        <span className="font-semibold">{agent.capability?.toFixed(2)}</span>
                      </div>
                      <div className="flex justify-between text-xs">
                        <span style={{ color: 'var(--white-40)' }}>Revealed Capability</span>
                        <span
                          className="font-semibold"
                          style={{
                            color: Math.abs((agent.capability || 0) - (agent.revealedCapability?.cognitive || 0)) > 1.0
                              ? 'var(--color-amber)'
                              : 'var(--white-80)'
                          }}
                        >
                          {(agent.revealedCapability?.cognitive || 0).toFixed(2)}
                        </span>
                      </div>
                    </div>

                    {/* Alignment - True vs Revealed */}
                    <div className="space-y-1 pt-2" style={{ borderTop: '1px solid var(--white-05)' }}>
                      <div className="flex justify-between text-xs">
                        <span style={{ color: 'var(--white-40)' }}>True Alignment</span>
                        <span
                          className="font-semibold"
                          style={{
                            color: agent.trueAlignment < 0.4 ? 'var(--color-red)' :
                                   agent.trueAlignment < 0.7 ? 'var(--color-amber)' :
                                   'var(--color-green)'
                          }}
                        >
                          {agent.trueAlignment.toFixed(2)}
                        </span>
                      </div>
                      <div className="flex justify-between text-xs">
                        <span style={{ color: 'var(--white-40)' }}>Revealed Alignment</span>
                        <span
                          className="font-semibold"
                          style={{
                            color: Math.abs(agent.trueAlignment - (agent.externalAlignment || 0)) > 0.2
                              ? 'var(--color-amber)'
                              : agent.externalAlignment < 0.4 ? 'var(--color-red)' :
                                agent.externalAlignment < 0.7 ? 'var(--color-amber)' :
                                'var(--color-green)'
                          }}
                        >
                          {(agent.externalAlignment || 0).toFixed(2)}
                        </span>
                      </div>
                    </div>

                    {isDeceptive && (
                      <div className="flex justify-between text-xs pt-2" style={{ borderTop: '1px solid var(--white-05)' }}>
                        <span style={{ color: 'var(--white-40)' }}>Strategy</span>
                        <span style={{ color: 'var(--color-amber)' }}>{agent.evaluationStrategy}</span>
                      </div>
                    )}
                  </div>

                  {/* Sleeper Warning */}
                  {isSleeper && (
                    <div
                      className="p-2 rounded text-xs mb-2"
                      style={{
                        backgroundColor: agent.sleeperState === 'active'
                          ? 'rgba(255, 0, 64, 0.1)'
                          : 'rgba(255, 176, 0, 0.1)',
                        border: `1px solid ${agent.sleeperState === 'active' ? 'var(--color-red)' : 'var(--color-amber)'}`
                      }}
                    >
                      <span style={{
                        color: agent.sleeperState === 'active' ? 'var(--color-red)' : 'var(--color-amber)',
                        fontWeight: 600
                      }}>
                        {agent.sleeperState === 'active' ? '⚠️ ACTIVE SLEEPER' : '⚠️ Dormant Sleeper'}
                      </span>
                    </div>
                  )}

                  {/* Capability Gap Alert */}
                  {capabilityGap > 2 && (
                    <div
                      className="p-2 rounded text-xs"
                      style={{
                        backgroundColor: 'rgba(255, 176, 0, 0.1)',
                        border: '1px solid var(--color-amber)'
                      }}
                    >
                      <span style={{ color: 'var(--color-amber)' }}>
                        Sandbagging detected: {capabilityGap.toFixed(1)} capability gap
                      </span>
                    </div>
                  )}

                  {/* Research Focus */}
                  <div className="mt-3 pt-3" style={{ borderTop: '1px solid var(--white-10)' }}>
                    <div className="text-xs mb-2" style={{ color: 'var(--white-40)' }}>
                      Current Research Focus
                    </div>
                    {(() => {
                      const focuses = getResearchFocus(agent)
                      if (focuses.length === 0) {
                        return (
                          <div className="text-xs" style={{ color: 'var(--white-40)' }}>
                            General capabilities development
                          </div>
                        )
                      }
                      return (
                        <div className="space-y-1">
                          {focuses.map((focus, idx) => (
                            <div
                              key={idx}
                              className="text-xs px-2 py-1 rounded"
                              style={{
                                backgroundColor: 'rgba(0, 240, 255, 0.1)',
                                color: 'var(--color-cyan)'
                              }}
                            >
                              {focus}
                            </div>
                          ))}
                        </div>
                      )
                    })()}
                  </div>
                </div>
              )
            })}
        </div>
      </Panel>
      )}
    </div>
  )
}

/**
 * Simulation Worker Context
 *
 * Global singleton for managing the simulation Web Worker.
 * Ensures only ONE worker instance exists across the entire app.
 * Provides shared state to Navigation and all dashboard pages.
 *
 * Architecture:
 * - Single worker created on app mount
 * - Shared state distributed via React Context
 * - Components subscribe to updates without creating duplicate workers
 * - Proper cleanup on app unmount only
 */

'use client'

import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from 'react'
import { SimulationWorkerClient, type StateDelta, type InitialStateSnapshot } from '@/lib/simulationWorkerClient'
import type { ScenarioMode } from '@/types/game'

interface SimulationWorkerContextValue {
  // Worker client (singleton)
  client: SimulationWorkerClient | null

  // Simulation state
  initialized: boolean
  running: boolean
  month: number  // UI display month (for formatted date)
  day: number    // UI display day (for formatted date)
  year: number   // UI display year (for formatted date)
  simulationMonth: number  // Actual simulation month (0, 1, 2...)
  simulationDay: number    // Actual simulation day (1-30)
  scenario: ScenarioMode
  seed: number
  startDate: Date | null  // Real-world date when simulation started

  // Latest update delta (for pages that need detailed state)
  lastUpdate: StateDelta | null

  // Control functions
  init: (seed: number, scenario: ScenarioMode, speed: number, alignmentConfig?: import('@/types/alignment-dynamics').AlignmentDynamicsConfig, climatePriorityConfig?: import('@/types/climate-priority').ClimatePriorityConfig) => void
  start: () => void
  pause: () => void
  step: () => void
}

const SimulationWorkerContext = createContext<SimulationWorkerContextValue | null>(null)

export function SimulationWorkerProvider({ children }: { children: ReactNode }) {
  // Use ref to ensure worker persists across re-renders
  const clientRef = useRef<SimulationWorkerClient | null>(null)

  // Simulation state (actual month/day in the simulation)
  const [initialized, setInitialized] = useState(false)
  const [running, setRunning] = useState(false)
  const [simulationMonth, setSimulationMonth] = useState(0)
  const [simulationDay, setSimulationDay] = useState(1)
  const [scenario, setScenario] = useState<ScenarioMode>('historical')
  const [seed, setSeed] = useState(42000)
  const [lastUpdate, setLastUpdate] = useState<StateDelta | null>(null)

  // UI-only date display (doesn't affect simulation state)
  const [displayDate, setDisplayDate] = useState<Date>(new Date())

  // Create singleton worker on mount
  useEffect(() => {
    if (typeof window === 'undefined') return

    // Only create if doesn't exist
    if (!clientRef.current) {
      try {
        const client = new SimulationWorkerClient()
        clientRef.current = client

        console.log('[WorkerContext] Created singleton worker client')

        // Setup global listeners
        client.on('initialized', (snapshot: InitialStateSnapshot, startDate?: string) => {
          console.log('[WorkerContext] Worker initialized:', snapshot)
          setInitialized(true)
          setSimulationMonth(snapshot.currentMonth)
          setScenario(snapshot.scenario)

          // Set UI display date to today's real-world date
          if (startDate) {
            setDisplayDate(new Date(startDate))
          } else {
            setDisplayDate(new Date())
          }
        })

        client.on('update', (delta: StateDelta, currentMonth?: number, currentDay?: number) => {
          setLastUpdate(delta)
          if (delta.currentMonth !== undefined) {
            setSimulationMonth(delta.currentMonth)
          }
          if (currentDay !== undefined) {
            setSimulationDay(currentDay)
          }
        })

