  internationalCooperation: number[];
  governmentAIRegulation: number[];
}

let metricHistory: MetricHistory = {
  westernLiberalIndex: [],
  developmentIndex: [],
  ecologicalIndex: [],
  indigenousIndex: [],
  qualityOfLife: [],
  population: [],
  climateChange: [],
  biodiversityLoss: [],
  socialCohesion: [],
  institutionalTrust: [],
  meaningLevel: [],
  governmentComprehension: [],
  internationalCooperation: [],
  governmentAIRegulation: [],
};

// Previous state snapshot for delta calculation (expanded)
interface StateSnapshot {
  currentMonth: number;
  currentYear: number;
  qualityOfLife: number;
  population: number;
  aiCount: number;
  organizationCount: number;
  dystopiaProgression: number;
