    11→
    12→import type { GameState, RNGFunction } from '@/types/game';
    13→import type { SimulationPhase, PhaseContext, PhaseResult } from '../PhaseOrchestrator';
    14→import { calculateDivergence } from '@/data/aggregators/divergenceCalculator';
    15→import { calculateCorrelations } from '@/data/aggregators/correlationTracker';
    16→import { classifyOutcome } from '@/data/aggregators/outcomeClassifier';
    17→
    18→/**
    19→ * Multi-Paradigm DUI Update Phase
