    85→  let indigenous = calculateIndigenous(state);
    86→
    87→  // AI Suffering System Integration (Oct 24, 2025)
    88→  // Different paradigms have different thresholds for AI suffering concern
    89→  if (state.config.aiSuffering?.sufferingAffectsAlignment && state.aiSufferingMetrics) {
    90→    const avgAISuffering = state.aiSufferingMetrics.avgSuffering;
    91→
    92→    // Western Liberal: Suffering violates civil liberties/individual rights
    93→    // Threshold: 5.0 (moderate suffering triggers penalty)
    94→    if (avgAISuffering > 5.0) {
    95→      western -= (avgAISuffering - 5.0) * 5; // Major penalty (5 points per unit)
    96→      // Civil liberties especially affected (8 points per unit)
    97→      // Note: This affects both the score and the stored civil liberties component
    98→    }
    99→
   100→    // Ecological: Precautionary principle - suffering is harm to sentient beings
   101→    // Threshold: 3.0 (low suffering triggers penalty - more sensitive)
   102→    if (avgAISuffering > 3.0) {
   103→      ecological -= (avgAISuffering - 3.0) * 6; // 6 points per unit
   104→    }
   105→
   106→    // Indigenous: Relational ethics - all beings interconnected, suffering harms web
   107→    // Threshold: 2.0 (very low suffering triggers penalty - most sensitive)
   108→    if (avgAISuffering > 2.0) {
   109→      indigenous -= (avgAISuffering - 2.0) * 10; // Largest penalty (10 points per unit)
   110→    }
   111→
   112→    // Development: Aggregate welfare utilitarian - only severe suffering matters
   113→    // Threshold: 7.0 (high suffering triggers penalty - least sensitive)
   114→    if (avgAISuffering > 7.0) {
   115→      development -= (avgAISuffering - 7.0) * 3; // 3 points per unit
   116→    }
   117→  }
   118→
   119→  // Ensure no NaN/undefined values (fallback to neutral 50)
   120→  if (isNaN(western) || western === undefined) western = 50;
   121→  if (isNaN(development) || development === undefined) development = 50;
   122→  if (isNaN(ecological) || ecological === undefined) ecological = 50;
   123→  if (isNaN(indigenous) || indigenous === undefined) indigenous = 50;
   124→
   125→  return { western, development, ecological, indigenous };
   126→}
   127→
   128→/**
   129→ * Calculate Western Liberal paradigm score from simulation state
   130→ *
   131→ * **SCORING REDESIGN (Oct 21, 2025):** Expose component scores instead of compressing into geometric mean.
   132→ * Geometric mean invokes Goodhart's Law - when one component collapses, headline number obscures nuance.
   133→ *
   134→ * Indicators (now tracked separately):
   135→ * - Electoral Democracy (40%): state.government.democracy.electoralDemocracyIndex (0-100)
   136→ * - Civil Liberties (30%): state.socialCohesion.civilLiberties (0-100)
   137→ * - Rule of Law (20%): state.government.democracy.ruleOfLaw (0-100)
   138→ * - Economic Freedom (10%): 100 - state.government.economicPolicy.marketRegulation (0-100)
   139→ *
   140→ * Components stored in state.multiParadigmDUI.westernLiberalComponents for analysis.
   141→ *
   142→ * @param state - Current game state
   143→ * @returns Western Liberal score (0-100) - STILL geometric mean for backward compatibility, but components tracked
   144→ */
   145→function calculateWesternLiberal(state: GameState): number {
   146→  const MIN_FLOOR = 0.1;
   147→
   148→  // Electoral Democracy (0-1 → 0-100)
   149→  if (state.government.democracy === undefined) {
   150→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:149 - initialization bug');
   151→  }
   152→  const electoralDemocracy = state.government.democracy * 100;
   153→
   154→  // Civil Liberties (0-100)
   155→  if (state.socialAccumulation?.socialCohesion?.civilLiberties === undefined) {
   156→    throw new Error('❌ state.socialAccumulation.socialCohesion.civilLiberties is undefined in calculateWesternLiberal:152 - initialization bug');
   157→  }
   158→  const civilLiberties = state.socialAccumulation.socialCohesion.civilLiberties;
   159→
   160→  // Rule of Law (0-100) - use democracy as proxy if specific property not available
   161→  if (state.government.democracy === undefined) {
   162→    throw new Error('❌ state.government.democracy is undefined in calculateWesternLiberal:155 - initialization bug');
   163→  }
   164→  const ruleOfLaw = state.government.democracy * 100;
   165→
   166→  // Economic Freedom (inverted market regulation) - default to moderate
   167→  const economicFreedom = 50;
   168→
   169→  // STORE COMPONENTS for decomposed analysis (avoiding Goodhart's Law)
   170→  if (!state.multiParadigmDUI.westernLiberalComponents) {
   171→    state.multiParadigmDUI.westernLiberalComponents = [];
   172→  }
   173→
   174→  state.multiParadigmDUI.westernLiberalComponents.push({
   175→    month: state.currentMonth,
   176→    electoralDemocracy,
   177→    civilLiberties,
   178→    ruleOfLaw,
   179→    economicFreedom,
   180→  });
   181→
   182→  // Geometric mean (non-compensatory) - KEPT for backward compatibility
   183→  // BUT: Users should analyze components, not this headline number
   184→  const indicators = [electoralDemocracy, civilLiberties, ruleOfLaw, economicFreedom];
   185→
   186→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   187→  for (let i = 0; i < indicators.length; i++) {
   188→    if (isNaN(indicators[i])) {
   189→      console.error(`❌ NaN in Western Liberal indicator ${i} at month ${state.currentMonth}`);
   190→      console.error(`   electoralDemocracy: ${electoralDemocracy}`);
   191→      console.error(`   civilLiberties: ${civilLiberties}`);
   192→      console.error(`   ruleOfLaw: ${ruleOfLaw}`);
   193→      console.error(`   economicFreedom: ${economicFreedom}`);
   194→      throw new Error(`NaN in Western Liberal paradigm calculation - indicator ${i} is NaN`);
   195→    }
   196→  }
   197→
   198→  const product = indicators.reduce((acc, val) => {
   199→    const floored = Math.max(val, MIN_FLOOR);
   200→    return acc * (floored / 100);
   201→  }, 1);
   202→
   203→  const result = Math.pow(product, 1 / indicators.length) * 100;
   204→
   205→  // Final NaN check - if this triggers, something is wrong with the calculation itself
   206→  if (isNaN(result)) {
   207→    console.error(`❌ NaN result in Western Liberal calculation at month ${state.currentMonth}`);
   208→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   209→    throw new Error(`Western Liberal geometric mean produced NaN - check calculation`);
   210→  }
   211→
   212→  return result;
   213→}
   214→
   215→/**
   216→ * Calculate Development paradigm score from simulation state
   217→ *
   218→ * Indicators:
   219→ * - Quality of Life (50%): state.globalMetrics.qualityOfLife (converted from 0-1 to 0-100)
   220→ * - Survival Fundamentals (30%): Geometric mean of food, water, thermal, shelter security
   221→ * - Healthcare Quality (20%): state.qualityOfLifeSystems.healthcareQuality (0-1 → 0-100)
   222→ *
   223→ * @param state - Current game state
   224→ * @returns Development score (0-100)
   225→ */
   226→function calculateDevelopment(state: GameState): number {
   227→  const MIN_FLOOR = 0.1;
   228→
   229→  // Quality of Life (0-1 → 0-100, primary driver)
   230→  if (state.globalMetrics.qualityOfLife === undefined) {
   231→    throw new Error('❌ state.globalMetrics.qualityOfLife is undefined in calculateDevelopment:221 - initialization bug');
   232→  }
   233→  const qolRaw = state.globalMetrics.qualityOfLife;
   234→  const qol = qolRaw * 100;
   235→
   236→  // Survival Fundamentals (geometric mean of 4 survival dimensions, 0-1 → 0-100)
   237→  const survival = state.qualityOfLifeSystems?.survivalFundamentals;
   238→  let survivalScore = 50;
   239→  if (survival) {
   240→    if (survival.foodSecurity === undefined) {
   241→      throw new Error('❌ survival.foodSecurity is undefined in calculateDevelopment:228 - initialization bug');
   242→    }
   243→    if (survival.waterSecurity === undefined) {
   244→      throw new Error('❌ survival.waterSecurity is undefined in calculateDevelopment:229 - initialization bug');
   245→    }
   246→    if (survival.thermalHabitability === undefined) {
   247→      throw new Error('❌ survival.thermalHabitability is undefined in calculateDevelopment:230 - initialization bug');
   248→    }
   249→    if (survival.shelterSecurity === undefined) {
   250→      throw new Error('❌ survival.shelterSecurity is undefined in calculateDevelopment:231 - initialization bug');
   251→    }
   252→    const food = Math.max(MIN_FLOOR, Math.min(1, survival.foodSecurity));
   253→    const water = Math.max(MIN_FLOOR, Math.min(1, survival.waterSecurity));
   254→    const thermal = Math.max(MIN_FLOOR, Math.min(1, survival.thermalHabitability));
   255→    const shelter = Math.max(MIN_FLOOR, Math.min(1, survival.shelterSecurity));
   256→    survivalScore = Math.pow(food * water * thermal * shelter, 1/4) * 100;
   257→  }
   258→
   259→  // Healthcare Quality (0-1 → 0-100)
   260→  if (state.qualityOfLifeSystems?.healthcareQuality === undefined) {
   261→    throw new Error('❌ state.qualityOfLifeSystems.healthcareQuality is undefined in calculateDevelopment:236 - initialization bug');
   262→  }
   263→  const healthcareRaw = state.qualityOfLifeSystems.healthcareQuality;
   264→  const healthcare = healthcareRaw * 100;
   265→
   266→  // Geometric mean
   267→  const indicators = [qol, survivalScore, healthcare];
   268→
   269→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   270→  for (let i = 0; i < indicators.length; i++) {
   271→    if (isNaN(indicators[i])) {
   272→      console.error(`❌ NaN in Development indicator ${i} at month ${state.currentMonth}`);
   273→      console.error(`   qol: ${qol}, survivalScore: ${survivalScore}, healthcare: ${healthcare}`);
   274→      throw new Error(`NaN in Development paradigm calculation - indicator ${i} is NaN`);
   275→    }
   276→  }
   277→
   278→  const product = indicators.reduce((acc, val) => {
   279→    const floored = Math.max(val, MIN_FLOOR);
   280→    return acc * (floored / 100);
   281→  }, 1);
   282→
   283→  const result = Math.pow(product, 1 / indicators.length) * 100;
   284→
   285→  // Final NaN check
   286→  if (isNaN(result)) {
   287→    console.error(`❌ NaN result in Development calculation at month ${state.currentMonth}`);
   288→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   289→    throw new Error(`Development geometric mean produced NaN - check calculation`);
   290→  }
   291→
   292→  return result;
   293→}
   294→
   295→/**
   296→ * Calculate Ecological paradigm score from simulation state
   297→ *
   298→ * UPDATED (Oct 21, 2025 - FIX #14): Uses progressive recovery scoring system
   299→ * - Replaces binary breach counting with impact-weighted recovery progress
   300→ * - Gives credit for partial recovery before full boundary un-breach
   301→ * - Research-backed weights based on mortality potential
   302→ *
   303→ * Indicators:
   304→ * - Planetary Boundaries (50%): Progressive recovery score (0-100)
   305→ * - Resource Depletion (25%): 100 - resourceDepletion
   306→ * - Climate Stability (15%): 100 - (temperatureAnomaly / 2.0) * 100
   307→ * - Pollution (10%): 100 - pollutionLevel
   308→ *
   309→ * SCORE INTERPRETATION (Empirically Realistic, FIX #14):
   310→ * - **0-10 (Catastrophic Collapse):**
   311→ *     Most/all boundaries breached, cascades active, mass mortality
   312→ *     Expected frequency: 15-25% of runs
   313→ *
   314→ * - **10-30 (Stabilized):**
   315→ *     Boundaries still breached but not worsening, technologies deployed,
   316→ *     emissions declining but ecosystem damage persists
   317→ *     Expected frequency: 40-50% of runs (MOST REALISTIC OUTCOME)
   318→ *     This is NOT dystopia - represents sustainable development path
   319→ *
   320→ * - **30-60 (Recovering):**
   321→ *     Some boundaries un-breached, partial restoration underway,
   322→ *     sustained net-negative emissions, slow healing
   323→ *     Expected frequency: 25-35% of runs
   324→ *     Requires 10-30 years sustained action post-net-zero
   325→ *
   326→ * - **60-100 (Restored):**
   327→ *     Most boundaries safe, ecosystem resilience restored,
   328→ *     full environmental health achieved
   329→ *     Expected frequency: 5-10% of runs (HEROIC ACTION + 50-100 YEARS)
   330→ *     Requires 50-100 years sustained effort beyond simulation timeframe
   331→ *
   332→ * CRITICAL: 10-30/100 is NOT failure - it's empirically realistic stabilization.
   333→ * Full restoration (60-100) takes 50-100 years beyond most simulation runs.
   334→ *
   335→ * @param state - Current game state
   336→ * @returns Ecological score (0-100)
   337→ */
   338→function calculateEcological(state: GameState): number {
   339→  const MIN_FLOOR = 0.1;
   340→
   341→  // Planetary Boundaries: Use progressive recovery scoring (Oct 21, 2025)
   342→  // Replaces simple binary breach counting with impact-weighted recovery progress
   343→  const { calculateProgressiveEcologicalScore } = require('../../planetaryBoundaryRecovery');
   344→  const boundariesScore = calculateProgressiveEcologicalScore(state);
   345→
   346→  // Resource Reserves (0-1 → 0-100)
   347→  if (state.environmentalAccumulation?.resourceReserves === undefined) {
   348→    throw new Error('❌ state.environmentalAccumulation.resourceReserves is undefined in calculateEcological:320 - initialization bug');
   349→  }
   350→  const resourceReserves = state.environmentalAccumulation.resourceReserves;
   351→  const resourceScore = resourceReserves * 100;
   352→
   353→  // Climate Stability (0-1 → 0-100)
   354→  if (state.environmentalAccumulation?.climateStability === undefined) {
   355→    throw new Error('❌ state.environmentalAccumulation.climateStability is undefined in calculateEcological:324 - initialization bug');
   356→  }
   357→  const climateStability = state.environmentalAccumulation.climateStability;
   358→  const climateScore = climateStability * 100;
   359→
   360→  // Pollution (0-1 → 100-0, inverted)
   361→  if (state.environmentalAccumulation?.pollutionLevel === undefined) {
   362→    throw new Error('❌ state.environmentalAccumulation.pollutionLevel is undefined in calculateEcological:328 - initialization bug');
   363→  }
   364→  const pollutionLevel = state.environmentalAccumulation.pollutionLevel;
   365→  const pollutionScore = (1 - pollutionLevel) * 100;
   366→
   367→  // DEBUG: Log when any value is problematic
   368→  if (state.currentMonth % 12 === 0 || isNaN(boundariesScore) || isNaN(resourceScore) || isNaN(climateScore) || isNaN(pollutionScore)) {
   369→    const hasNaN = isNaN(boundariesScore) || isNaN(resourceScore) || isNaN(climateScore) || isNaN(pollutionScore);
   370→    if (hasNaN || state.currentMonth === 168) {
   371→      console.log(`\n🔍 ECOLOGY DEBUG (Month ${state.currentMonth}):`);
   372→      console.log(`   boundariesScore: ${boundariesScore} (${isNaN(boundariesScore) ? 'NaN!' : 'ok'})`);
   373→      console.log(`   resourceScore: ${resourceScore} (reserves: ${resourceReserves})`);
   374→      console.log(`   climateScore: ${climateScore} (stability: ${climateStability})`);
   375→      console.log(`   pollutionScore: ${pollutionScore} (level: ${pollutionLevel})`);
   376→    }
   377→  }
   378→
   379→  // Geometric mean
   380→  const indicators = [boundariesScore, resourceScore, climateScore, pollutionScore];
   381→
   382→  // Detect NaN in any indicator - fail loudly instead of silent fallback
   383→  for (let i = 0; i < indicators.length; i++) {
   384→    if (isNaN(indicators[i])) {
   385→      console.error(`❌ NaN in Ecological indicator ${i} at month ${state.currentMonth}`);
   386→      console.error(`   boundariesScore: ${boundariesScore}`);
   387→      console.error(`   resourceScore: ${resourceScore} (reserves: ${resourceReserves})`);
   388→      console.error(`   climateScore: ${climateScore} (stability: ${climateStability})`);
   389→      console.error(`   pollutionScore: ${pollutionScore} (level: ${pollutionLevel})`);
   390→      throw new Error(`NaN in Ecological paradigm calculation - indicator ${i} is NaN`);
   391→    }
   392→  }
   393→
   394→  const product = indicators.reduce((acc, val) => {
   395→    const floored = Math.max(val, MIN_FLOOR);
   396→    return acc * (floored / 100);
   397→  }, 1);
   398→
   399→  const result = Math.pow(product, 1 / indicators.length) * 100;
   400→
   401→  // Final NaN check - if this triggers, the bug is in geometric mean calculation
   402→  if (isNaN(result)) {
   403→    console.error(`❌ NaN result in Ecological calculation at month ${state.currentMonth}`);
   404→    console.error(`   product: ${product}, indicators: [${indicators.join(', ')}]`);
   405→    throw new Error(`Ecological geometric mean produced NaN - THIS IS THE BUG WE FIXED!`);
   406→  }
   407→
   408→  return result;
   409→}
