/**
 * Quality of Life Helper Functions
 *
 * Calculate aggregate tier scores from multi-dimensional QoL system
 * for backward compatibility with scripts and logging
 */

import { QualityOfLifeSystems } from '../types/quality-of-life';

/**
 * Calculate Survival Tier (Tier 0) aggregate
 * Average of survival fundamentals
 */
export function calculateSurvivalTier(qol: QualityOfLifeSystems): number {
  const { foodSecurity, waterSecurity, thermalHabitability, shelterSecurity } = qol.survivalFundamentals;
  return (foodSecurity + waterSecurity + thermalHabitability + shelterSecurity) / 4;
}

/**
 * Calculate Material Tier (Tier 1) aggregate
 * Average of material needs
 */
export function calculateMaterialTier(qol: QualityOfLifeSystems): number {
  return (qol.materialAbundance + qol.energyAvailability + qol.physicalSafety) / 3;
}

/**
 * Calculate Psychological Tier (Tier 2) aggregate
 * Average of psychological needs
 */
export function calculatePsychologicalTier(qol: QualityOfLifeSystems): number {
  return (qol.mentalHealth + qol.meaningAndPurpose + qol.socialConnection + qol.autonomy) / 4;
}

/**
 * Calculate Social Tier (Tier 3) aggregate
 * Average of social needs
 */
export function calculateSocialTier(qol: QualityOfLifeSystems): number {
  return (qol.politicalFreedom + qol.informationIntegrity + qol.communityStrength + qol.culturalVitality) / 4;
}

/**
 * Calculate Health Tier (Tier 4) aggregate
 * Average of health and longevity
 */
export function calculateHealthTier(qol: QualityOfLifeSystems): number {
  return (qol.healthcareQuality + qol.longevityGains + (1 - qol.diseasesBurden)) / 3;
}

/**
 * Calculate Environmental Tier (Tier 5) aggregate
 * Average of environmental quality (pollution inverted)
 */
export function calculateEnvironmentalTier(qol: QualityOfLifeSystems): number {
  return (qol.ecosystemHealth + qol.climateStability + (1 - qol.pollutionLevel)) / 3;
}

/**
 * Calculate all tier aggregates
 */
export function calculateAllTiers(qol: QualityOfLifeSystems) {
  return {
    survivalTier: calculateSurvivalTier(qol),
    materialTier: calculateMaterialTier(qol),
    psychologicalTier: calculatePsychologicalTier(qol),
    socialTier: calculateSocialTier(qol),
    healthTier: calculateHealthTier(qol),
    environmentalTier: calculateEnvironmentalTier(qol),
  };
}

/**
 * Quality of Life Aggregation
 *
 * Aggregates multi-dimensional QoL metrics into weighted overall score.
 *
 * Research basis: Multi-dimensional wellbeing frameworks (Sen, Nussbaum)
 * Weights reflect relative importance from empirical studies.
 *
 * Tier weights:
 * - Basic Needs: 30% (material, energy, safety)
 * - Psychological: 25% (mental health, meaning, connection, autonomy)
 * - Social: 20% (freedom, information, community, culture)
 * - Health: 15% (healthcare, longevity, disease burden)
 * - Environmental: 10% (ecosystem, climate, pollution)
 */

import type { QualityOfLifeSystems } from '@/types/game';

/**
 * Calculate weighted quality of life from all component systems
 *
 * This replaces the simple QoL calculation with a nuanced system that tracks:
 * - Basic needs (30%): material, energy, safety
 * - Psychological (25%): mental health, meaning, connection, autonomy
 * - Social (20%): freedom, information, community, culture
 * - Health (15%): healthcare, longevity, disease burden
 * - Environmental (10%): ecosystem, climate, pollution
 *
 * Enables "dark valley" dynamics where some dimensions can drop
 * while others are maintained, allowing recovery trajectories
 *
 * @param systems - The quality of life dimensions to aggregate
 * @returns Weighted quality of life score [0, ~1.5] where 1.0 is "good"
 */
export function calculateQualityOfLife(systems: QualityOfLifeSystems): number {
  // Validate all inputs - fail loudly if any are NaN
  if (!validateQoLSystems(systems)) {
    // Find which value is NaN
    const nanFields: string[] = [];
    Object.entries(systems).forEach(([key, value]) => {
      if (typeof value === 'number' && (isNaN(value) || !isFinite(value))) {
        nanFields.push(`${key}: ${value}`);
      }
    });

    console.error(`❌ NaN/Infinity in QoL systems`);
    console.error(`   Invalid fields: ${nanFields.join(', ')}`);
    console.error(`   Full systems: ${JSON.stringify(systems, null, 2)}`);
    throw new Error(`NaN in Quality of Life calculation - fields: ${nanFields.join(', ')}`);
  }

  // Basic Needs (30% weight)
  const basicNeeds = (
    systems.materialAbundance * 0.4 +    // Food, shelter, goods
    systems.energyAvailability * 0.3 +   // Energy access
    systems.physicalSafety * 0.3          // Safety from violence
  ) * 0.3;

  // Psychological Needs (25% weight)
  const psychological = (
    systems.mentalHealth * 0.3 +         // Mental wellness
    systems.meaningAndPurpose * 0.3 +    // Life satisfaction
    systems.socialConnection * 0.2 +      // Relationships
    systems.autonomy * 0.2                // Self-determination
  ) * 0.25;

  // Social Needs (20% weight)
  const social = (
    systems.politicalFreedom * 0.3 +     // Democracy, rights
    systems.informationIntegrity * 0.3 +  // Truth vs propaganda
    systems.communityStrength * 0.2 +     // Local cohesion
    systems.culturalVitality * 0.2        // Art, creativity
  ) * 0.2;

  // Health and Longevity (15% weight)
  const health = (
    systems.healthcareQuality * 0.4 +    // Medical outcomes
    systems.longevityGains * 0.3 +        // Lifespan increases
    (1 - systems.diseasesBurden) * 0.3    // Low disease burden
  ) * 0.15;

  // Environmental (10% weight)
  const environmental = (
    systems.ecosystemHealth * 0.4 +      // Nature, biodiversity
    systems.climateStability * 0.3 +      // Stable weather
    (1 - systems.pollutionLevel) * 0.3    // Clean air/water
  ) * 0.1;

  const result = basicNeeds + psychological + social + health + environmental;

  // Final NaN check on result
  if (isNaN(result) || !isFinite(result)) {
    console.error(`❌ NaN/Infinity in QoL RESULT`);
    console.error(`   basicNeeds: ${basicNeeds}`);
    console.error(`   psychological: ${psychological}`);
    console.error(`   social: ${social}`);
    console.error(`   health: ${health}`);
    console.error(`   environmental: ${environmental}`);
    throw new Error(`Quality of Life calculation produced NaN/Infinity`);
  }

/**
 * Quality of Life System - Public API
 *
 * This index re-exports all public functions for backward compatibility.
 * The original qualityOfLife.ts file is now split into focused modules:
 * - core.ts: Main QoL calculation engine
 * - dimensions.ts: Survival fundamentals (food, water, shelter, habitability)
 * - penalties.ts: Penalty calculations (unemployment, trauma, population collapse)
 * - regional.ts: Regional distribution and inequality metrics
 * - aggregation.ts: Tier aggregation and weighting
 * - cache/regionalCache.ts: Performance optimization for regional lookups
 *
 * Performance improvements:
 * - Regional cache eliminates O(n) array scans → O(1) Map lookups
 * - Pre-computed dimension weights
 * - Modular structure enables targeted optimizations
 *
 * Target: 20-30% reduction in QoL calculation time
 */

// === CORE FUNCTIONS ===
export { updateQualityOfLifeSystems, initializeQualityOfLifeSystems } from './core';

// === AGGREGATION ===
export { calculateQualityOfLife, calculateQualityOfLifeOptimized, DIMENSION_WEIGHTS, validateQoLSystems } from './aggregation';

// === SURVIVAL FUNDAMENTALS ===
// FIX (Oct 25, 2025): Removed calculateFoodSecurity (now regional only)
// FIX (Oct 25, 2025): calculateSurvivalFundamentals renamed to calculateNonFoodSurvivalMetrics
export {
  calculateNonFoodSurvivalMetrics,
  calculateWaterSecurity,
  calculateThermalHabitability,
  calculateShelterSecurity
} from './dimensions';

// === REGIONAL DISTRIBUTION ===
export { calculateDistributionMetrics, calculateGiniCoefficient, calculateRegionalInequality } from './regional';

// === PENALTIES ===
export {
  calculateUnemploymentPenalty,
  calculateFoodSecurityPenalty,
  calculatePopulationCollapsePenalty,
  calculateTraumaPenalty,
  calculateTraumaInstitutionalErosion,
  calculateUBIFloor,
  calculateUBIMentalHealthBonus,
  calculateUBIShelterFloor,
  calculatePostScarcityMultipliers
} from './penalties';

// === CACHE ===
export type { RegionalCache, RegionalData } from './cache/regionalCache';
export { buildRegionalCache, getRegionalData, isCacheValid, getCachedRegions } from './cache/regionalCache';

// === MORTALITY & FAMINES ===
export { calculateEnvironmentalMortality, checkRegionalFamineRisk } from './mortality';
export type { EnvironmentalMortalityBreakdown } from './mortality';

