    10→ * - Environmental (ecosystem, climate, pollution)
    11→ * - Distribution metrics (regional inequality)
    12→ *
    13→ * Performance optimizations:
    14→ * - Regional cache to eliminate O(n) array scans
    15→ * - Pre-computed dimension weights
    16→ * - Modular structure for easier optimization
    17→ */
    18→
    19→import type { GameState, QualityOfLifeSystems } from '@/types/game';
    20→import { getTrustInAI } from '../socialCohesion';
    21→import { calculateNonFoodSurvivalMetrics } from './dimensions';
    22→import {
    23→  calculateUnemploymentPenalty,
    24→  calculateFoodSecurityPenalty,
    25→  calculatePopulationCollapsePenalty,
    26→  calculateTraumaPenalty,
    27→  calculateTraumaInstitutionalErosion,
    28→  calculateUBIFloor,
    29→  calculateUBIMentalHealthBonus,
    30→  calculateUBIShelterFloor,
    31→  calculatePostScarcityMultipliers,
    32→} from './penalties';
    33→import { calculateDistributionMetrics, calculateRegionalInequality } from './regional';
    34→import type { RegionalCache } from './cache/regionalCache';
    35→
    36→/**
    37→ * Update all quality of life dimensions based on current game state
    38→ *
    39→ * This function calculates how each QoL dimension changes based on:
    40→ * - Economic conditions (unemployment, stage, wealth)
    41→ * - AI impacts (beneficial/harmful actions, capability)
    42→ * - Government policies (legitimacy, control, regulations)
    43→ * - Social dynamics (adaptation, trust, stability)
    44→ *
    45→ * Returns updated QoL systems that can then be aggregated via calculateQualityOfLife()
    46→ *
    47→ * Performance note: This function is called every simulation step, so optimizations matter.
    48→ * Regional cache is passed in to enable memoization across multiple calls in same month.
    49→ */
    50→export function updateQualityOfLifeSystems(
    51→  state: GameState,
    52→  regionalCache: RegionalCache | null = null
    53→): QualityOfLifeSystems {
    54→  const { globalMetrics, society, aiAgents, government, qualityOfLifeSystems: current } = state;
    55→
    56→  const totalAICapability = aiAgents.reduce((sum, ai) => sum + ai.capability, 0);
    57→  const avgAlignment = aiAgents.reduce((sum, ai) => sum + ai.alignment, 0) / Math.max(1, aiAgents.length);
    58→  const beneficialActions = aiAgents.reduce((sum, ai) => sum + ai.beneficialActions, 0);
    59→  const harmfulActions = aiAgents.reduce((sum, ai) => sum + ai.harmfulActions, 0);
    60→  const economicStage = globalMetrics.economicTransitionStage;
    61→
    62→  // Detect NaN in key inputs - fail loudly
    63→  if (isNaN(totalAICapability)) {
    64→    console.error(`❌ NaN totalAICapability in updateQualityOfLifeSystems at month ${state.currentMonth}`);
    65→    console.error(`   AI agents: ${aiAgents.map(ai => `${ai.id}: ${ai.capability}`).join(', ')}`);
    66→    throw new Error(`NaN in totalAICapability - check AI agent capabilities`);
    67→  }
    68→
    69→  if (isNaN(economicStage)) {
    70→    console.error(`❌ NaN economicStage in updateQualityOfLifeSystems at month ${state.currentMonth}`);
    71→    console.error(`   economicTransitionStage: ${globalMetrics.economicTransitionStage}`);
    72→    throw new Error(`NaN in economicStage - check globalMetrics.economicTransitionStage`);
    73→  }
    74→
    75→  // Phase 1.2: Check for UBI (strengthens safety net effects)
    76→  const hasUBI = government.activeRegulations.some(reg => reg.includes('UBI'));
    77→  const ubiVariant = government.structuralChoices.ubiVariant || 'none';
    78→  const hasGenerousUBI = ubiVariant === 'generous';
    79→
    80→  // === BASIC NEEDS ===
    81→
    82→  // Material abundance: AI capability helps, unemployment hurts, stage matters
    83→  const aiProductionBonus = totalAICapability * avgAlignment * 0.1;
    84→  const unemploymentPenalty = calculateUnemploymentPenalty(society.unemploymentLevel, economicStage);
    85→  const wealthBonus = globalMetrics.wealthDistribution * 0.3;
    86→  let materialAbundance = 0.8 + aiProductionBonus + unemploymentPenalty + wealthBonus;
    87→
    88→  // UBI floor
    89→  if (hasUBI) {
    90→    const ubiFloor = calculateUBIFloor(economicStage, hasGenerousUBI);
    91→    materialAbundance = Math.max(materialAbundance, ubiFloor);
    92→  }
