      // Quality of Life (Oct 26, 2025 - bottom-up aggregation)
      qualityOfLife: 0.85 * 0.3 + (3.5 / 4) * 0.3 + 0.90 * 0.2 + (1 - 0.5) * 0.1 + (1 - 0.7) * 0.05 + (1 - 0.3) * 0.05,

