export interface PlanetaryBoundariesSystem {
  // === THE 9 BOUNDARIES ===
  boundaries: Record<BoundaryName, PlanetaryBoundary>;
  // === AGGREGATE METRICS ===
  boundariesBreached: number;       // How many beyond safe zone (2025: 7/9)
  boundariesWorsening: number;      // How many getting worse
