  ) / 3 : 0.5;

  const qolEnvironmental = qolSystems ? (
    qolSystems.ecosystemHealth + qolSystems.climateStability + (1 - qolSystems.pollutionLevel)
  ) / 3 : 0.5;

  // Sleeper analysis
  const sleepers = activeAIs.filter((ai: AIAgent) => 
