  const monthsElapsed = MAX_MONTHS;
  const avgPopulation = (initialPopulation + finalPopulation) / 2;
  const deathsNatural = (avgPopulation * pop.baselineDeathRate * (monthsElapsed / 12)) * 1000; // Convert to millions

